from fabric import task
from invoke.exceptions import Exit

from benchmark.local import LocalBench
from benchmark.logs import ParseError, LogParser
from benchmark.utils import BenchError, Print
from benchmark.plot import Ploter, PlotError
from alibaba.instance import InstanceManager
from alibaba.remote import Bench
from alibaba.collector import Collector


@task
def local(ctx):
    ''' Run benchmarks on localhost '''
    bench_params = {
        'nodes': 4,
        'rate': 10000,
        'tx_size': 256,
        'faults': 0,
        'duration': 30,
    }
    node_params = {
        'consensus': {
            'node_sync_delay': 500,
            'timeout_delay': 1000,
            'sync_retry_delay': 10_000,
            'max_payload_size': 1000,
            'min_block_delay': 0,
            'network_delay': 10000, # message delay on the leaders' proposals during DDoS, valid when ddos is True
            'ddos': False, # True for DDoS attack on the leader, False otherwise
            'random_ddos': False, # 100% delay
            'random_ddos_chance': 0, # 0-100, 0 for no random delay
            'lambda': 10,
            'unstable_ddos': False,
            'unstable_delay': 500,
        },
        'mempool': {
            'queue_capacity': 10_000,
            'sync_retry_delay': 100_000,
            'max_payload_size': 256_000,
            'min_block_delay': 0
        },
    }
    try:
        ret = LocalBench(bench_params, node_params).run(debug=False).result()
        print(ret)
    except BenchError as e:
        Print.error(e)


@task
def create(ctx, nodes=1): # 每个地域创建 nodes 台机器，每台机器运行一个节点
    ''' Create `nodes` Alibaba Cloud instances per region '''
    try:
        InstanceManager.make().create_instances(nodes)
    except BenchError as e:
        Print.error(e)


@task
def destroy(ctx):
    ''' Destroy the testbed '''
    try:
        InstanceManager.make().terminate_instances()
    except BenchError as e:
        Print.error(e)


@task
def start(ctx, max=10):
    ''' Start at most `max` machines per data center '''
    try:
        InstanceManager.make().start_instances(max)
    except BenchError as e:
        Print.error(e)


@task
def stop(ctx):
    ''' Stop all machines '''
    try:
        InstanceManager.make().stop_instances()
    except BenchError as e:
        Print.error(e)


@task
def info(ctx):
    ''' Display connect information about all the available machines '''
    try:
        InstanceManager.make().print_info()
    except BenchError as e:
        Print.error(e)


@task
def install(ctx):
    ''' Prepare all machines (cloud-init, tmux) to run uploaded binaries '''
    try:
        Bench(ctx).install()
    except BenchError as e:
        Print.error(e)


@task
def remote(ctx):
    ''' Run benchmarks on Alibaba Cloud '''
    bench_params = {
        'nodes': [4],
        'rate': [450_000, 550_000],
        'tx_size': 16,
        'faults': 0,
        'duration': 100,
        'runs': 1,
    }
    node_params = {
        'consensus': {
            'node_sync_delay': 10_000,
            'timeout_delay': 10_000,
            'sync_retry_delay': 100_000,
            'max_payload_size': 1_000, # size of payloads in block
            'min_block_delay': 0, # minimum delay between blocks
            'network_delay': 20_000, # message delay on the leaders' proposals during DDoS
            'ddos': False, # True for DDoS attack on the leader, False otherwise
            'random_ddos': False,
            'random_ddos_chance': 5,
            'lambda': 10,
            'unstable_ddos': False, # True for DDoS attack on the next leader, False otherwise
            'unstable_delay': 500, # Optimistic delay
        },
        'mempool': {
            'queue_capacity': 100_000,
            'sync_retry_delay': 100_000,
            'max_payload_size': 16_000, # payload size: 1_000 txs of 16 B
            'min_block_delay': 0 # minimum delay between payloads
        },
    }
    try:
        Bench(ctx).run(bench_params, node_params, debug=False)
    except BenchError as e:
        Print.error(e)


@task
def plot(ctx):
    ''' Plot performance using the logs generated by "fab remote" '''
    plot_params = {
        'nodes': [10, 20, 50],
        'tx_size': 512,
        'faults': [0],
        'max_latency': [3_000, 6_000]
    }
    try:
        Ploter.plot(plot_params)
    except PlotError as e:
        Print.error(BenchError('Failed to plot performance', e))


@task
def kill(ctx):
    ''' Stop any Jcarus execution on all machines '''
    try:
        Bench(ctx).kill()
    except BenchError as e:
        Print.error(e)


@task
def logs(ctx):
    ''' Print a summary of the logs '''
    try:
        print(LogParser.process('./logs').result())
    except ParseError as e:
        Print.error(BenchError('Failed to parse logs', e))


def _collector_command(ctx, operation, **kwargs):
    try:
        return getattr(Collector(ctx), operation)(**kwargs)
    except Exception as error:
        failure = error if isinstance(error, BenchError) else BenchError('Collector command failed', error)
        Print.error(failure)
        raise Exit(code=1) from error


@task
def collector_create(ctx):
    ''' Create or reuse the independent collector (starts it if stopped) '''
    _collector_command(ctx, 'create')


@task
def collector_setup(ctx):
    ''' Install Jcarus/Python and copy configured SSH/Alibaba credentials '''
    _collector_command(ctx, 'setup')


@task
def collector_ssh(ctx):
    ''' Open an interactive SSH shell in the collector benchmark directory '''
    _collector_command(ctx, 'ssh')


@task
def collector_download(ctx, directory=''):
    ''' Download all collector results into a new unique directory '''
    _collector_command(ctx, 'download', directory=directory, snapshot=True)


@task
def collector_sync(ctx, directory=''):
    ''' Pull changed results; remote overwrites local, without deleting local files '''
    _collector_command(ctx, 'download', directory=directory, snapshot=False)


@task
def collector_info(ctx):
    ''' Display collector identity, status, SSH command and result directories '''
    _collector_command(ctx, 'info')


@task
def collector_destroy(ctx):
    ''' Destroy only the collector after typing its identity to confirm '''
    _collector_command(ctx, 'destroy')
